24	// A check context over a literal file map — the same {files, read} surface the
25	// engine's runner passes, with nothing else the rules are allowed to touch.
26	const ctxOf = (files) => ({
27	  files: Object.keys(files),
28	  read: (f) => (f in files ? files[f] : null),
29	});
30	
31	const run = (rule, files) => rule.run(ctxOf(files));
